A.bfh=new B.e(4,"Does your mom work on Saturday?","","\uc5b4\uba38\ub2c8\ub294 \ud1a0\uc694\uc77c\uc5d0 \uc77c\ud558\uc138\uc694?","Does",A.Og)
A.baB=new B.e(5,"Do we need an umbrella?","","\uc6b0\ub9ac \uc6b0\uc0b0\uc774 \ud544\uc694\ud574\uc694?","Do",A.Oh)
